import java.io.*;
import java.util.*;

public class Main {
    static int[] head, to, next;
    static int edgeCnt = 0;

    static void addEdge(int u, int v) {
        to[edgeCnt] = v;
        next[edgeCnt] = head[u];
        head[u] = edgeCnt++;
    }

    static class State {
        int h1 = -1, h2 = -1, k1 = 0;
        long c1 = 0, c2 = 0, sq1 = 0;

        void reset() {
            h1 = -1;
            h2 = -1;
            k1 = 0;
            c1 = 0;
            c2 = 0;
            sq1 = 0;
        }

        void add(int h, long c) {
            if (h > h1) {
                h2 = h1;
                c2 = c1;
                h1 = h;
                c1 = c;
                sq1 = c * c;
                k1 = 1;
            } else if (h == h1) {
                c1 += c;
                sq1 += c * c;
                k1++;
            } else if (h > h2) {
                h2 = h;
                c2 = c;
            } else if (h == h2) {
                c2 += c;
            }
        }

        int maxDist() {
            if (k1 >= 2) return 2 * h1;
            if (h2 != -1) return h1 + h2;
            return -1;
        }

        long count() {
            if (k1 >= 2) {
                return (c1 * c1 - sq1) / 2;
            } else if (h2 != -1) {
                return c1 * c2;
            }
            return 0;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null) return;

        int N = Integer.parseInt(first.trim());

        head = new int[N + 1];
        Arrays.fill(head, -1);
        to = new int[2 * (N - 1)];
        next = new int[2 * (N - 1)];

        for (int i = 0; i < N - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            addEdge(x, y);
            addEdge(y, x);
        }

        int[] parent = new int[N + 1];
        int[] order = new int[N];
        int idx = 0;

        int[] stack = new int[N];
        int top = 0;
        parent[1] = -1;
        stack[top++] = 1;

        while (top > 0) {
            int u = stack[--top];
            order[idx++] = u;
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == parent[u]) continue;
                parent[v] = u;
                stack[top++] = v;
            }
        }

        int[] height = new int[N + 1];
        int[] cnt = new int[N + 1];

        State st = new State();
        int bestDist = -1;
        long bestCount = 0;

        for (int i = N - 1; i >= 0; i--) {
            int u = order[i];

            st.reset();
            st.add(0, 1);

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (parent[v] == u) {
                    st.add(height[v] + 1, cnt[v]);
                }
            }

            long localCount = st.count();
            if (localCount > 0) {
                int localDist = st.maxDist();
                if (localDist > bestDist) {
                    bestDist = localDist;
                    bestCount = localCount;
                } else if (localDist == bestDist) {
                    bestCount += localCount;
                }
            }

            if (st.h1 <= 0) {
                height[u] = 0;
                cnt[u] = 1;
            } else {
                height[u] = st.h1;
                cnt[u] = (int) st.c1;
            }
        }

        System.out.println(bestDist + 1);
        System.out.println(bestCount);
    }
}
